/**
 * Text field (spec/02 §2.1): [label] above the grey control (surfaceSunken, top corners 8 dp, ≥ 48 dp, 12 dp inside,
 * 1 dp borderStrong baseline), the value in body; [placeholder] textMuted while empty; [suffix] („Gläser“) in label
 * textMuted after the value; under it [help] in caption textMuted with an optional end-aligned [counter] („0 / 120“).
 * [error] = the 2 dp danger baseline and the error glyph in danger before the message in text; TalkBack reads it as the
 * field's error. The focus ring of §3 stands around the control while the field has focus. [singleLine] = false is
 * the web's textarea. Keyboard type and IME action are the caller's ([keyboardOptions], [keyboardActions]).
 * [optional] = a voluntary field (D99 (3)): „(optional)“ after the label in textMuted, TalkBack reads „Notiz,
 * optional“; required fields carry no mark. [trailing] (§14.12) = one SbIconButton at the control's end („Kalender“),
 * where the end padding drops to 0. [minLines] (§14.12) = the lines a multi-line field starts with (1 = one line that
 * grows). The value never gets a hyphen while it is edited (spec/07 §3.1): an overlong word breaks at the line end.
 */
@Composable
fun SbTextField(
    value: String,
    onValueChange: (String) -> Unit,
    label: String,
    modifier: Modifier = Modifier,
    placeholder: String? = null,
    suffix: String? = null,
    help: String? = null,
    counter: String? = null,
    error: String? = null,
    enabled: Boolean = true,
    singleLine: Boolean = true,
    keyboardOptions: KeyboardOptions = KeyboardOptions.Default,
    keyboardActions: KeyboardActions = KeyboardActions.Default,
    optional: Boolean = false,
    trailing: (@Composable () -> Unit)? = null,
    minLines: Int = if (singleLine) 1 else 2,
) {
    SbFieldInput(
        value = value,
        onValueChange = onValueChange,
        label = label,
        showLabel = true,
        optional = optional,
        modifier = modifier,
        placeholder = placeholder,
        suffix = suffix,
        help = help,
        counter = counter,
        error = error,
        enabled = enabled,
        singleLine = singleLine,
        keyboardOptions = keyboardOptions,
        keyboardActions = keyboardActions,
        interaction = remember { MutableInteractionSource() },
        leading = null,
        trailing = trailing,
        minLines = minLines,
    )
}

/** Tab and Shift + Tab leave a field of several lines, where they would write a tab and trap the focus (CHECKS.md §85). */
@Composable
private fun Modifier.sbTabLeaves(): Modifier {
    val focus = LocalFocusManager.current
    return onPreviewKeyEvent { e ->
        if (e.key != Key.Tab) return@onPreviewKeyEvent false
        if (e.type == KeyEventType.KeyDown) focus.moveFocus(if (e.isShiftPressed) FocusDirection.Previous else FocusDirection.Next)
        true
    }
}

/** The text input of SbTextField and SbSearchField: the label, the control with [leading] and [trailing], the notes. */
@Composable
internal fun SbFieldInput(
    value: String,
    onValueChange: (String) -> Unit,
    label: String,
    showLabel: Boolean,
    optional: Boolean,
    modifier: Modifier,
    placeholder: String?,
    suffix: String?,
    help: String?,
    counter: String?,
    error: String?,
    enabled: Boolean,
    singleLine: Boolean,
    keyboardOptions: KeyboardOptions,
    keyboardActions: KeyboardActions,
    interaction: MutableInteractionSource,
    leading: (@Composable () -> Unit)?,
    trailing: (@Composable () -> Unit)?,
    minLines: Int = if (singleLine) 1 else 2,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    // §14.12: a growing field (one line at first) pads its text 12 dp above and below, so a second line never touches
    // the control's top or its baseline; one line still stands in 48 dp at font scale 1 (12 + 24 + 12)
    val grows = !singleLine && minLines <= 1
    BasicTextField(
        value = value,
        onValueChange = onValueChange,
        modifier = modifier
            .fillMaxWidth()
            .then(if (singleLine) Modifier else Modifier.sbTabLeaves())
            .semantics { if (error != null) error(error) },
        enabled = enabled,
        // spec/07 §3.1: no hyphen while editing, an overlong word breaks at the line end (the one exception to D99 (1))
        textStyle = ty.body.copy(color = if (enabled) c.text else c.textMuted, hyphens = Hyphens.None),
        keyboardOptions = keyboardOptions,
        keyboardActions = keyboardActions,
        singleLine = singleLine,
        minLines = if (singleLine) 1 else minLines.coerceAtLeast(1),
        interactionSource = interaction,
        cursorBrush = SolidColor(c.text),
        decorationBox = { inner ->
            Column(verticalArrangement = Arrangement.spacedBy(t.space.s1)) {
                if (showLabel) SbFieldLabel(label, optional, enabled)
                Row(
                    Modifier
                        .sbFieldControl(interaction, error != null, enabled)
                        .padding(start = t.space.s3, end = if (trailing != null) t.space.s0 else t.space.s3)
                        .padding(vertical = if (singleLine || grows) t.space.s0 else t.space.s3),
                    verticalAlignment = if (singleLine) Alignment.CenterVertically else Alignment.Top,
                    horizontalArrangement = Arrangement.spacedBy(t.space.s2),
                ) {
                    leading?.invoke()
                    Box(Modifier.weight(1f).then(if (grows) Modifier.padding(vertical = t.space.s3) else Modifier)) {
                        // a hidden label is the field's name as a drawn label is: merged text, not a content description
                        if (!showLabel) Box(Modifier.semantics { this[SemanticsProperties.Text] = listOf(AnnotatedString(label)) })
                        if (value.isEmpty() && placeholder != null) {
                            // D111 (3): a one-line placeholder that does not fit at large text ends in „…“; the label names the field in full
                            Text(placeholder, style = ty.body, color = c.textMuted, maxLines = if (singleLine) 1 else Int.MAX_VALUE,
                                overflow = if (singleLine) TextOverflow.Ellipsis else TextOverflow.Clip)
                        }
                        inner()
                    }
                    if (suffix != null) {
                        Text(
                            suffix,
                            style = ty.label,
                            color = c.textMuted,
                            maxLines = 1,
                            modifier = if (grows) Modifier.padding(vertical = t.space.s3) else Modifier,
                        )
                    }
                    trailing?.invoke()
                }
                SbFieldNotes(help, counter, error)
            }
        },
    )
}

/**
 * The label above a field (spec/02 §2.1) in label: text, textMuted while disabled. [optional] (D99 (3)) adds a space and
 * „(optional)“ (fieldOptional from the words table) in textMuted at the body weight, the web's .sb-optional; it wraps
 * with the label. TalkBack reads „<label>, optional“ instead of the parentheses.
 */
@Composable
internal fun SbFieldLabel(label: String, optional: Boolean, enabled: Boolean) {
    val c = SebaroTheme.colors
    val ty = SebaroTheme.typography
    val ink = if (enabled) c.text else c.textMuted
    if (!optional) {
        Text(label, style = ty.label, color = ink)
        return
    }
    val word = sbMessages().fieldOptional
    Text(
        buildAnnotatedString {
            append(label)
            append(" ")
            withStyle(SpanStyle(color = c.textMuted, fontWeight = ty.body.fontWeight)) { append("($word)") }
        },
        style = ty.label,
        color = ink,
        modifier = Modifier.clearAndSetSemantics { this[SemanticsProperties.Text] = listOf(AnnotatedString("$label, $word")) },
    )
}

/**
 * The control of a field (spec/02 §2.1): the focus ring of §3 around it while [interaction] is focused, surfaceSunken
 * with 8 dp top corners, at least 48 dp, the baseline: 1 dp borderStrong, [error] 2 dp danger, disabled 1 dp border.
 */
@Composable
internal fun Modifier.sbFieldControl(interaction: InteractionSource, error: Boolean, enabled: Boolean): Modifier {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val shape = RoundedCornerShape(topStart = t.radius.control, topEnd = t.radius.control)
    val line = when {
        error -> c.danger
        !enabled -> c.border
        else -> c.borderStrong
    }
    val width = if (error) t.borderWidth.control * 2 else t.borderWidth.control
    return this
        .sbFocusRing(interaction, shape)
        .fillMaxWidth()
        .heightIn(min = t.size.controlMd)
        .clip(shape)
        .background(c.surfaceSunken)
        .drawBehind {
            val w = width.toPx()
            drawRect(line, Offset(0f, size.height - w), Size(size.width, w))
        }
}

/**
 * Under a field: the [error] (the error glyph 16 dp in danger, centred on the message's first line: 2 dp down at font
 * scale 1, as the web; then the message in caption text; hidden from TalkBack, the field carries it as its error),
 * then [help] in caption textMuted with [counter] at the end. [spoken] (a group's error, spec/02 §2.4): no focusable node
 * carries the error, so the sentence is read as text and, when it appears, said once as a polite live region.
 */
@Composable
internal fun SbFieldNotes(help: String?, counter: String?, error: String?, spoken: Boolean = false) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val line = with(LocalDensity.current) { ty.caption.lineHeight.toDp() }
    if (error != null) {
        Row(
            if (spoken) {
                Modifier.semantics(mergeDescendants = true) { liveRegion = LiveRegionMode.Polite }
            } else {
                Modifier.clearAndSetSemantics { }
            },
            horizontalArrangement = Arrangement.spacedBy(t.space.s1),
        ) {
            Icon(
                SebaroIcons.Filled16.Error,
                contentDescription = null,
                tint = c.danger,
                modifier = Modifier.padding(top = ((line - t.size.iconSm) / 2).coerceAtLeast(t.space.s0)).size(t.size.iconSm),
            )
            Text(error, style = ty.caption, color = c.text)
        }
    }
    if (help != null || counter != null) {
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(t.space.s3)) {
            Text(help ?: "", style = ty.caption, color = c.textMuted, modifier = Modifier.weight(1f))
            if (counter != null) {
                Text(
                    counter,
                    style = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings),
                    color = c.textMuted,
                    softWrap = false,
                )
            }
        }
    }
}
